"""Seed-panel summaries and the permitted evidence wording (PROTOCOL.md sections 9.2 and 9.5).

The across-seed spread and the trajectory-bootstrap interval are different sources of variation and are never
merged. The wording rules are applied by code so the report cannot call an exploratory comparison "demonstrated".
"""

from typing import Dict, Mapping, Optional, Sequence

import numpy as np

# Banned in every generated result statement (PROTOCOL.md 9.5). Static disclaimers that NEGATE these words
# ("not independent", "not blind") are fixed text in the report and are not generated by this module.
BANNED_PHRASES = (
    "confirmatory", "confirmed", "validated", "proves", "proven", "control-free", "independent", "blind", "relies on control",
    "equivalent", "negligible",
)
STATUSES = ("primary", "secondary", "exploratory", "sensitivity", "technical", "descriptive")


def seed_panel(values_by_seed: Mapping[int, float]) -> Dict[str, object]:
    """Descriptive spread of a per-seed quantity. No interval across seeds is computed."""
    v = np.array([values_by_seed[s] for s in sorted(values_by_seed)], dtype=float)
    if v.size == 0 or not np.isfinite(v).all():
        raise ValueError("seed panel needs finite values for every seed")
    return {
        "n_seeds": int(v.size), "mean": float(v.mean()), "median": float(np.median(v)), "min": float(v.min()), "max": float(v.max()),
        "sd_ddof1": float(v.std(ddof=1)) if v.size > 1 else None,
        "note": "descriptive spread over training seeds; not a confidence interval and not combined with bootstrap uncertainty",
    }


def sign_consistent(deltas: Sequence[float]) -> bool:
    """True iff every delta is strictly positive or every delta is strictly negative (a zero is inconsistent)."""
    d = np.asarray(deltas, dtype=float)
    return bool(d.size > 0 and (np.all(d > 0) or np.all(d < 0)))


def assert_wording_clean(text: str) -> None:
    low = text.lower()
    hit = [p for p in BANNED_PHRASES if p in low]
    if hit:
        raise ValueError(f"banned wording in a generated statement: {hit}")


def evidence_statement(status: str, ci_lo: Optional[float], ci_hi: Optional[float], per_seed_deltas: Sequence[float],
                       adj_lo: Optional[float] = None, adj_hi: Optional[float] = None) -> Dict[str, object]:
    """The only sentence the report may use about a comparison. Primary contrasts may be called demonstrated
    under the stated conditions; everything else is only ever 'observed'."""
    if status not in STATUSES:
        raise ValueError(f"unknown status {status!r}")
    if ci_lo is None or ci_hi is None:
        out = {"label": "undefined", "marginal_level_only": False,
               "text": "The interval is undefined (no defined bootstrap replicate); no statement about a difference is made."}
    else:
        excludes = not (ci_lo <= 0.0 <= ci_hi)
        if status == "primary":
            if not excludes:
                out = {"label": "no_difference_demonstrated", "marginal_level_only": False,
                       "text": "No difference was demonstrated under this protocol (the interval includes 0). This does not show that the two conditions perform alike."}
            else:
                direction_positive = ci_lo > 0.0
                d = np.asarray(per_seed_deltas, dtype=float)
                same = bool(d.size > 0 and (np.all(d > 0) if direction_positive else np.all(d < 0)))
                if not same:
                    out = {"label": "inconsistent_across_seeds", "marginal_level_only": False,
                           "text": "The interval excludes 0 but the per-seed deltas do not all share its sign: the result is inconsistent across seeds."}
                else:
                    marginal = adj_lo is not None and adj_hi is not None and adj_lo <= 0.0 <= adj_hi
                    text = ("A difference was demonstrated under this protocol (the marginal 95% interval excludes 0 and every per-seed "
                            "delta shares its sign).")
                    if marginal:
                        text += " This is marginal-level evidence only: the Bonferroni-adjusted interval includes 0."
                    out = {"label": "difference_demonstrated", "marginal_level_only": bool(marginal), "text": text}
        else:
            tag = f"{status}, unadjusted"
            if excludes:
                out = {"label": "difference_observed", "marginal_level_only": False,
                       "text": f"A difference was observed ({tag}; the interval excludes 0)."}
            else:
                out = {"label": "no_difference_observed", "marginal_level_only": False,
                       "text": f"No difference was observed ({tag}; the interval includes 0)."}
    assert_wording_clean(out["text"])
    out["status"] = status
    return out
